INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('dune', 'physical', 'Dune', 'Frank Herbert', 'https://covers.openlibrary.org/b/isbn/9780441172719-L.jpg', 688, 'Set on the desert planet Arrakis, Dune follows Paul Atreides as his family becomes entangled in a struggle for control over the most valuable resource in the universe.', ARRAY['Science Fiction', 'Space Opera', 'Politics']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('the-hobbit', 'physical', 'The Hobbit', 'J.R.R. Tolkien', 'https://covers.openlibrary.org/b/isbn/9780547928227-L.jpg', 310, 'Bilbo Baggins leaves his quiet life behind and joins a company of dwarves on a dangerous journey to reclaim their homeland from a dragon.', ARRAY['Fantasy', 'Adventure', 'Classic']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('1984', 'physical', '1984', 'George Orwell', 'https://covers.openlibrary.org/b/isbn/9780451524935-L.jpg', 328, 'A dystopian novel about surveillance, propaganda, and the struggle for individual freedom.', ARRAY['Dystopian', 'Political Fiction', 'Classic']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('the-little-prince', 'physical', 'The Little Prince', 'Antoine de Saint-Exupéry', 'https://covers.openlibrary.org/b/isbn/9780156012195-L.jpg', 96, 'A philosophical tale about friendship, love, and human connection.', ARRAY['Fiction', 'Philosophy', 'Classic']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('the-alchemist', 'ebook', 'The Alchemist', 'Paulo Coelho', 'https://covers.openlibrary.org/b/isbn/9780062315007-L.jpg', 208, 'A young shepherd follows a recurring dream and embarks on a journey to discover his personal legend.', ARRAY['Fiction', 'Philosophy', 'Adventure']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('atomic-habits', 'ebook', 'Atomic Habits', 'James Clear', 'https://covers.openlibrary.org/b/isbn/9780735211292-L.jpg', 320, 'A practical guide to building better habits through small, consistent changes.', ARRAY['Self-Help', 'Psychology', 'Productivity']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('the-name-of-the-wind', 'physical', 'The Name of the Wind', 'Patrick Rothfuss', 'https://covers.openlibrary.org/b/isbn/9780756404741-L.jpg', 662, 'Kvothe recounts the extraordinary story of his childhood, education, and rise to legendary status.', ARRAY['Fantasy', 'Adventure', 'Coming of Age']);--> statement-breakpoint
INSERT INTO "shujia_books" ("slug", "book_format", "title", "author", "cover_url", "total_pages", "description", "categories") VALUES ('norwegian-wood', 'physical', 'Norwegian Wood', 'Haruki Murakami', 'https://covers.openlibrary.org/b/isbn/9780375704024-L.jpg', 298, 'A nostalgic coming-of-age story about love, loss, memory, and loneliness in 1960s Tokyo.', ARRAY['Literary Fiction', 'Romance', 'Coming of Age']);--> statement-breakpoint
